<?php
namespace App\Http\Middleware;use Closure;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Schema;
class AuditAdminActivity {public function handle($request,Closure $next){$response=$next($request);if($request->session()->has('admin_id')&&!$request->isMethod('get')&&Schema::hasTable('admin_activity_logs')){try{$input=$request->except(['_token','password','password_confirmation','admin_password']);DB::table('admin_activity_logs')->insert(['admin_id'=>$request->session()->get('admin_id'),'admin_name'=>$request->session()->get('admin_name'),'action'=>$this->action($request),'method'=>$request->method(),'path'=>'/'.ltrim($request->path(),'/'),'ip_hash'=>hash_hmac('sha256',(string)$request->ip(),config('app.key')),'details'=>json_encode($input),'created_at'=>now()]);}catch(\Throwable $e){}}return $response;}private function action($request){return ucwords(str_replace(['-','/'],' ',trim($request->path(),'/')));}}
